=== FILE: tb/tb_mac8.v ===
// Self-checking scoreboard testbench for mac8.
// Reference model written from interface_spec.md section 2 (MAC-RESET,
// MAC-CLEAR, MAC-ACC, MAC-HOLD, MAC-SAT, MAC-STICKY), independently of the RTL.
// Pass: prints "TEST PASSED". Fail: prints "TEST FAILED" after the first
// mismatch, with the inputs, prior model state, expected and actual outputs.
`timescale 1ns / 1ps
module tb_mac8;
    reg         clk   = 1'b0;
    reg         rst_n = 1'b0;
    reg         clr   = 1'b0;
    reg         en    = 1'b0;
    reg  [7:0]  a     = 8'd0;
    reg  [7:0]  b     = 8'd0;
    wire [23:0] acc;
    wire        sat;

    mac8 dut (
        .clk  (clk),
        .rst_n(rst_n),
        .clr  (clr),
        .en   (en),
        .a    (a),
        .b    (b),
        .acc  (acc),
        .sat  (sat)
    );

    always #5 clk = ~clk;

    // ------------------------------------------------------------------
    // Reference model state (from the specification, not the RTL)
    // ------------------------------------------------------------------
    reg  [23:0] m_acc;
    reg         m_sat;
    reg         m_valid;     // model state defined (after first reset/clear)
    reg  [23:0] p_acc;       // model state before the current edge
    reg         p_sat;
    reg  [31:0] m_prod;
    reg  [31:0] m_sum;

    integer cycle;
    integer checks;
    integer seed;
    integer i;
    integer n_sat_set;
    integer n_sat_cleared;
    integer n_sat_held;

    reg         r_rst, r_clr, r_en;
    reg  [7:0]  r_a, r_b;
    reg  [31:0] rr;

    // ------------------------------------------------------------------
    // Failure reporting
    // ------------------------------------------------------------------
    task fail;
        begin
            $display("TEST FAILED at cycle %0d (t=%0t) after %0d checks", cycle, $time, checks);
            $finish;
        end
    endtask

    // ------------------------------------------------------------------
    // Model update for one rising edge, following spec section 2
    // ------------------------------------------------------------------
    task model_step;
        input       r;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        begin
            if (!r) begin                       // MAC-RESET
                m_acc   = 24'd0;
                m_sat   = 1'b0;
                m_valid = 1'b1;
            end else if (c) begin               // MAC-CLEAR (wins over en)
                m_acc   = 24'd0;
                m_sat   = 1'b0;
                m_valid = 1'b1;
            end else if (e) begin               // MAC-ACC, unsigned operands
                m_prod = {24'd0, ia};
                m_prod = m_prod * {24'd0, ib};
                m_sum  = {8'd0, m_acc};
                m_sum  = m_sum + m_prod;
                if (m_sum > 32'h00FFFFFF) begin // MAC-SAT: strictly more than max
                    m_acc = 24'hFFFFFF;
                    m_sat = 1'b1;
                end else begin
                    m_acc = m_sum[23:0];        // flag unchanged (MAC-STICKY)
                end
            end
            // else MAC-HOLD: nothing changes
        end
    endtask

    // ------------------------------------------------------------------
    // Scoreboard comparison after each edge
    // ------------------------------------------------------------------
    task check_outputs;
        input       r;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        begin
            if (m_valid) begin
                checks = checks + 1;
                if ((acc !== m_acc) || (sat !== m_sat)) begin
                    $display("SCOREBOARD MISMATCH at cycle %0d (t=%0t)", cycle, $time);
                    $display("  inputs at edge: rst_n=%b clr=%b en=%b a=%0d (0x%02h) b=%0d (0x%02h)",
                             r, c, e, ia, ia, ib, ib);
                    $display("  model before edge: acc=0x%06h sat=%b", p_acc, p_sat);
                    $display("  expected: acc=0x%06h sat=%b", m_acc, m_sat);
                    $display("  got:      acc=0x%06h sat=%b", acc, sat);
                    fail;
                end
            end
        end
    endtask

    // ------------------------------------------------------------------
    // One clock cycle: drive on falling edge, model on rising edge, check
    // ------------------------------------------------------------------
    task step;
        input       r;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        begin
            @(negedge clk);
            rst_n = r;
            clr   = c;
            en    = e;
            a     = ia;
            b     = ib;
            @(posedge clk);
            p_acc = m_acc;
            p_sat = m_sat;
            model_step(r, c, e, ia, ib);
            if (m_sat && !p_sat)                       n_sat_set     = n_sat_set + 1;
            if (p_sat && !m_sat)                       n_sat_cleared = n_sat_cleared + 1;
            if (p_sat && m_sat)                        n_sat_held    = n_sat_held + 1;
            #1;
            cycle = cycle + 1;
            check_outputs(r, c, e, ia, ib);
        end
    endtask

    // ------------------------------------------------------------------
    // Directed check against hard-coded expected values (checks the DUT and
    // the model, so a model error cannot hide a design error)
    // ------------------------------------------------------------------
    task expect_const;
        input [23:0]     ea;
        input            es;
        input [8*48-1:0] what;
        begin
            checks = checks + 1;
            if ((acc !== ea) || (sat !== es)) begin
                $display("DIRECTED CHECK FAILED [%0s] at cycle %0d: expected acc=0x%06h sat=%b, got acc=0x%06h sat=%b",
                         what, cycle, ea, es, acc, sat);
                $display("  last inputs: rst_n=%b clr=%b en=%b a=%0d b=%0d", rst_n, clr, en, a, b);
                fail;
            end
            if ((m_acc !== ea) || (m_sat !== es)) begin
                $display("REFERENCE MODEL SELF-CHECK FAILED [%0s]: model acc=0x%06h sat=%b, expected acc=0x%06h sat=%b",
                         what, m_acc, m_sat, ea, es);
                fail;
            end
        end
    endtask

    task fill_squares;          // 258 x (255*255) from zero = 0xFFFD02
        integer k;
        begin
            for (k = 0; k < 258; k = k + 1)
                step(1'b1, 1'b0, 1'b1, 8'd255, 8'd255);
        end
    endtask

    task pick_operand;
        output [7:0] v;
        reg    [31:0] t;
        begin
            t = $random(seed);
            case (t[2:0])
                3'd0:    v = 8'd0;
                3'd1:    v = 8'd255;
                3'd2:    v = 8'd1;
                3'd3:    v = 8'd128;
                3'd4:    v = 8'd255 - {5'd0, t[10:8]};
                default: v = t[15:8];
            endcase
        end
    endtask

    // Watchdog
    initial begin
        #10_000_000;
        $display("WATCHDOG TIMEOUT");
        fail;
    end

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        m_acc = 24'd0; m_sat = 1'b0; m_valid = 1'b0;
        p_acc = 24'd0; p_sat = 1'b0;
        cycle = 0; checks = 0;
        n_sat_set = 0; n_sat_cleared = 0; n_sat_held = 0;
        seed = 32'h0C0FFEE5;

        // T1: reset wins over an offered accumulate (MAC-RESET)
        step(1'b0, 1'b0, 1'b1, 8'd255, 8'd255);
        expect_const(24'd0, 1'b0, "reset with en high");
        step(1'b0, 1'b0, 1'b1, 8'd255, 8'd255);
        expect_const(24'd0, 1'b0, "reset held with en high");
        step(1'b0, 1'b1, 1'b1, 8'd255, 8'd255);
        expect_const(24'd0, 1'b0, "reset with clr and en high");

        // T2: unsigned accumulate and hold (MAC-ACC, MAC-HOLD)
        step(1'b1, 1'b0, 1'b1, 8'd3, 8'd5);
        expect_const(24'd15, 1'b0, "3*5");
        step(1'b1, 1'b0, 1'b0, 8'd200, 8'd200);
        expect_const(24'd15, 1'b0, "hold with en low");
        step(1'b1, 1'b0, 1'b1, 8'd255, 8'd255);
        expect_const(24'd65040, 1'b0, "255*255 unsigned");
        step(1'b1, 1'b0, 1'b1, 8'd128, 8'd1);
        expect_const(24'd65168, 1'b0, "128*1 unsigned");
        step(1'b1, 1'b0, 1'b1, 8'd0, 8'd255);
        expect_const(24'd65168, 1'b0, "0*255");
        step(1'b1, 1'b0, 1'b1, 8'd255, 8'd0);
        expect_const(24'd65168, 1'b0, "255*0");

        // T3: clear wins over accumulate (MAC-CLEAR)
        step(1'b1, 1'b1, 1'b1, 8'd255, 8'd255);
        expect_const(24'd0, 1'b0, "clr wins over en");
        step(1'b1, 1'b1, 1'b0, 8'd0, 8'd0);
        expect_const(24'd0, 1'b0, "clr with en low");

        // T4: reach exactly 0xFFFFFF without saturating, then overflow by one
        fill_squares;
        expect_const(24'hFFFD02, 1'b0, "258 x 255*255");
        step(1'b1, 1'b0, 1'b1, 8'd255, 8'd3);
        expect_const(24'hFFFFFF, 1'b0, "exactly max, no saturation");
        step(1'b1, 1'b0, 1'b1, 8'd0, 8'd7);
        expect_const(24'hFFFFFF, 1'b0, "max plus zero product");
        step(1'b1, 1'b0, 1'b0, 8'd255, 8'd255);
        expect_const(24'hFFFFFF, 1'b0, "hold at max");
        step(1'b1, 1'b0, 1'b1, 8'd1, 8'd1);
        expect_const(24'hFFFFFF, 1'b1, "max plus one saturates");

        // T5: sticky flag (MAC-STICKY)
        step(1'b1, 1'b0, 1'b0, 8'd255, 8'd255);
        expect_const(24'hFFFFFF, 1'b1, "sticky through hold");
        step(1'b1, 1'b0, 1'b1, 8'd0, 8'd0);
        expect_const(24'hFFFFFF, 1'b1, "sticky through zero product");
        step(1'b1, 1'b0, 1'b1, 8'd255, 8'd255);
        expect_const(24'hFFFFFF, 1'b1, "sticky through full product");
        for (i = 0; i < 5; i = i + 1) step(1'b1, 1'b0, 1'b0, 8'd17, 8'd33);
        expect_const(24'hFFFFFF, 1'b1, "sticky through repeated hold");

        // T6: clear removes saturation; flag stays 0 afterwards
        step(1'b1, 1'b1, 1'b1, 8'd1, 8'd1);
        expect_const(24'd0, 1'b0, "clr clears saturation");
        step(1'b1, 1'b0, 1'b1, 8'd2, 8'd3);
        expect_const(24'd6, 1'b0, "accumulate after clr");

        // T7: large overflow would wrap to 0x00FB03; must saturate
        step(1'b1, 1'b1, 1'b0, 8'd0, 8'd0);
        expect_const(24'd0, 1'b0, "clr before overflow test");
        fill_squares;
        expect_const(24'hFFFD02, 1'b0, "refill to 0xFFFD02");
        step(1'b1, 1'b0, 1'b1, 8'd255, 8'd255);
        expect_const(24'hFFFFFF, 1'b1, "large overflow saturates");

        // T8: reset removes saturation even with en high
        step(1'b0, 1'b0, 1'b1, 8'd255, 8'd255);
        expect_const(24'd0, 1'b0, "reset clears saturation");

        // T9: carry boundary: 0xFFFFFE + 2 just exceeds max
        fill_squares;
        step(1'b1, 1'b0, 1'b1, 8'd191, 8'd4);
        expect_const(24'hFFFFFE, 1'b0, "reach 0xFFFFFE");
        step(1'b1, 1'b0, 1'b1, 8'd1, 8'd2);
        expect_const(24'hFFFFFF, 1'b1, "0xFFFFFE + 2 saturates");
        step(1'b1, 1'b1, 1'b0, 8'd0, 8'd0);
        expect_const(24'd0, 1'b0, "clr after boundary test");

        // R1: random, rare clear/reset so saturation is reached repeatedly
        for (i = 0; i < 20000; i = i + 1) begin
            rr    = $random(seed);
            r_rst = (rr[11:0]  == 12'd0) ? 1'b0 : 1'b1;
            r_clr = (rr[21:12] == 10'd0) ? 1'b1 : 1'b0;
            r_en  = (rr[23:22] != 2'd0);
            pick_operand(r_a);
            pick_operand(r_b);
            step(r_rst, r_clr, r_en, r_a, r_b);
        end

        // R2: random, frequent clear/reset and hold
        for (i = 0; i < 10000; i = i + 1) begin
            rr    = $random(seed);
            r_rst = (rr[7:0]   == 8'd0) ? 1'b0 : 1'b1;
            r_clr = (rr[15:12] == 4'd0) ? 1'b1 : 1'b0;
            r_en  = rr[20];
            pick_operand(r_a);
            pick_operand(r_b);
            step(r_rst, r_clr, r_en, r_a, r_b);
        end

        $display("coverage: saturation set %0d times, held %0d edges, cleared %0d times",
                 n_sat_set, n_sat_held, n_sat_cleared);
        $display("TEST PASSED: %0d checks over %0d cycles", checks, cycle);
        $finish;
    end
endmodule
=== END FILE ===

